1	// Cloudflare DNS API client (API-token auth).
2	//
3	// Plain server-side module (NO "use server") — safe to import from server
4	// actions and the worker; never bundled to the client. Talks to the Cloudflare
5	// v4 REST API using a customer-supplied API token (scoped to Zone → DNS → Edit
6	// for their zone). The token is passed in per call — this module never reads it
7	// from the environment or persists it.
8	//
9	// Every function throws a clear CloudflareError on a non-success response so
10	// callers can surface a friendly message; callers that must stay tolerant wrap
11	// these in try/catch.
12	
13	const CF_API = "https://api.cloudflare.com/client/v4";
14	
15	export class CloudflareError extends Error {
16	  constructor(
17	    message: string,
18	    public status?: number,
19	    public code?: number,
20	  ) {
21	    super(message);
22	    this.name = "CloudflareError";
23	  }
24	}
25	
26	type CfEnvelope<T> = {
27	  success: boolean;
28	  errors?: { code: number; message: string }[];
29	  result: T;
30	};
31	
32	/** Core request helper — attaches the bearer token, parses the v4 envelope and
33	 * throws CloudflareError on transport failure or a `success:false` payload. */
34	async function cfRequest<T>(
35	  token: string,
36	  method: "GET" | "POST" | "PUT",
37	  path: string,
38	  body?: unknown,
39	): Promise<T> {
40	  const url = `${CF_API}${path.startsWith("/") ? path : `/${path}`}`;
41	
42	  let res: Response;
43	  try {
44	    res = await fetch(url, {
45	      method,
46	      headers: {
47	        Authorization: `Bearer ${token}`,
48	        "Content-Type": "application/json",
49	        Accept: "application/json",
50	      },
51	      body: body === undefined ? undefined : JSON.stringify(body),
52	      cache: "no-store",
53	    });
54	  } catch (e) {
55	    throw new CloudflareError(
56	      `Cloudflare unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
57	    );
58	  }
59	
60	  const text = await res.text();
61	  let parsed: CfEnvelope<T> | null = null;
62	  try {
63	    parsed = text ? (JSON.parse(text) as CfEnvelope<T>) : null;
64	  } catch {
65	    // fall through to a generic error below
66	  }
67	
68	  if (!parsed || parsed.success !== true) {
69	    const first = parsed?.errors?.[0];
70	    // 403/9109 → token lacks permission or is invalid; surface a stable message.
71	    const msg = first?.message ?? `Cloudflare ${method} ${path} -> HTTP ${res.status}`;
72	    throw new CloudflareError(msg, res.status, first?.code);
73	  }
74	
75	  return parsed.result;
76	}
77	
78	/**
79	 * Confirm an API token is valid and active (`GET /user/tokens/verify`). Returns
80	 * true only when Cloudflare reports the token status as "active". Never throws
81	 * for an ordinary invalid/expired token — returns false — but rethrows a genuine
82	 * transport failure so the caller can distinguish "rejected" from "unreachable".
83	 */
84	export async function cfVerifyToken(token: string): Promise<boolean> {
85	  try {
86	    const result = await cfRequest<{ status?: string }>(token, "GET", "/user/tokens/verify");
87	    return String(result?.status ?? "").toLowerCase() === "active";
88	  } catch (e) {
89	    if (e instanceof CloudflareError && (e.status === 400 || e.status === 401 || e.status === 403)) {
90	      return false;
91	    }
92	    throw e;
93	  }
94	}
95	
96	/**
97	 * Resolve a zone name (registrable domain) to its Cloudflare zone id, or null
98	 * when the token can't see a zone by that exact name. `GET /zones?name=<zone>`.
99	 */
100	export async function cfFindZoneId(token: string, zoneName: string): Promise<string | null> {
101	  const name = zoneName.trim().toLowerCase().replace(/\.$/, "");
102	  const result = await cfRequest<{ id: string; name: string }[]>(
103	    token,
104	    "GET",
105	    `/zones?name=${encodeURIComponent(name)}&status=active&per_page=5`,
106	  );
107	  const zone = Array.isArray(result)
108	    ? result.find((z) => z.name?.toLowerCase() === name) ?? result[0]
109	    : undefined;
110	  return zone?.id ?? null;
111	}
112	
113	export type CfDnsInput = {
114	  type: "TXT" | "MX";
115	  /** Fully-qualified record name, e.g. `_dmarc.example.com` or the zone apex. */
116	  name: string;
117	  content: string;
118	  priority?: number;
119	};
120	
121	export type CfUpsertResult = {
122	  name: string;
123	  type: "TXT" | "MX";
124	  action: "created" | "updated";
125	};
126	
127	type CfRecord = { id: string; type: string; name: string; content: string; priority?: number };
128	
129	// Strip surrounding quotes Cloudflare may echo on TXT content, for comparison.
130	function unquote(s: string): string {
131	  return s.trim().replace(/^"(.*)"$/s, "$1");
132	}
133	
134	/**
135	 * Decide whether an existing record is "the same kind" as one we manage, so an
136	 * upsert updates it in place rather than creating a duplicate. TXT records are
137	 * matched by their leading tag (SPF/DKIM/DMARC/ownership), MX by the mail host
138	 * it points at — so we never clobber a customer's unrelated records at the apex.
139	 */
140	function sameKind(desired: CfDnsInput, existing: CfRecord): boolean {
141	  if (existing.type !== desired.type) return false;
142	  if (desired.type === "MX") {
143	    return unquote(existing.content).replace(/\.$/, "").toLowerCase() ===
144	      desired.content.replace(/\.$/, "").toLowerCase();
145	  }
146	  const want = desired.content.toLowerCase();
147	  const have = unquote(existing.content).toLowerCase();
148	  for (const tag of ["nxeon-verify=", "v=spf1", "v=dkim1", "v=dmarc1"]) {
149	    if (want.startsWith(tag)) return have.startsWith(tag);
150	  }
151	  // No recognised tag — fall back to an exact name+type match (single record).
152	  return true;
153	}
154	
155	/**
156	 * Create or update each desired record in the given zone. For every record we
157	 * list the existing records at that exact name+type, update the one of the same
158	 * kind if present (PUT), else create a new one (POST). Returns one result row
159	 * per input describing what happened. Throws CloudflareError on API failure.
160	 */
161	export async function cfUpsertRecords(
162	  token: string,
163	  zoneId: string,
164	  records: CfDnsInput[],
165	): Promise<CfUpsertResult[]> {
166	  const out: CfUpsertResult[] = [];
167	
168	  for (const rec of records) {
169	    const existing = await cfRequest<CfRecord[]>(
170	      token,
171	      "GET",
172	      `/zones/${zoneId}/dns_records?type=${rec.type}&name=${encodeURIComponent(rec.name)}&per_page=100`,
173	    );
174	    const match = Array.isArray(existing) ? existing.find((e) => sameKind(rec, e)) : undefined;
175	
176	    const body: Record<string, unknown> = {
177	      type: rec.type,
178	      name: rec.name,
179	      content: rec.content,
180	      ttl: 1, // 1 = automatic
181	    };
182	    if (rec.type === "MX") body.priority = rec.priority ?? 10;
183	
184	    if (match) {
185	      await cfRequest(token, "PUT", `/zones/${zoneId}/dns_records/${match.id}`, body);
186	      out.push({ name: rec.name, type: rec.type, action: "updated" });
187	    } else {
188	      await cfRequest(token, "POST", `/zones/${zoneId}/dns_records`, body);
189	      out.push({ name: rec.name, type: rec.type, action: "created" });
190	    }
191	  }
192	
193	  return out;
194	}
