1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { randomBytes } from "node:crypto";
5	import { resolveTxt, resolveMx } from "node:dns/promises";
6	import { z } from "zod";
7	import { db } from "./db";
8	import { requireUser } from "./auth";
9	import { requireArea } from "./rbac";
10	import { checkRateLimit } from "./rate-limit";
11	import { debitWallet, InsufficientBalanceError } from "./wallet";
12	import { addMonths } from "./billing-terms";
13	import { encryptSecret, decryptSecret } from "./crypto-box";
14	import { currentPromo, promoPriceCents } from "./promotions";
15	import {
16	  mailcowConfigured,
17	  mcCreateDomain,
18	  mcDomainExists,
19	  mcCreateMailbox,
20	  mcDeleteMailbox,
21	  mcSetMailboxActive,
22	  mcSetMailboxPassword,
23	  mcGetDkim,
24	} from "./mailcow";
25	import { cfVerifyToken, cfFindZoneId, cfUpsertRecords, CloudflareError } from "./cloudflare-dns";
26	
27	/**
28	 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
29	 * publish these at their registrar so mail flows through the Nxeon mail server;
30	 * customers whose domain is inside Nxeon have this managed for them.
31	 */
32	const MAIL_HOST = "mail.nxeon.cloud";
33	const MAIL_MX_PRIORITY = 10;
34	const SPF_VALUE = "v=spf1 include:nxeon.cloud ~all";
35	const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
36	const DKIM_SELECTOR = "dkim";
37	
38	// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
39	const domainRe =
40	  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
41	
42	export type DnsRecord = {
43	  type: "TXT" | "MX";
44	  label: string; // human label for the row
45	  host: string; // record host / name
46	  value: string;
47	  priority?: number;
48	  note?: string;
49	};
50	
51	/**
52	 * Business Email — mailbox hosting per registered domain.
53	 *
54	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
55	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
56	 * which debits the wallet, then manages individual `Mailbox` rows under it.
57	 *
58	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
59	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
60	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
61	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
62	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
63	 * order flow; the row persists and can be retried via retryMailboxProvision.
64	 *
65	 * This module owns:
66	 *   - orderEmailHosting (customer subscribe)
67	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
68	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
69	 */
70	
71	type Result = { error?: string; ok?: boolean };
72	
73	/**
74	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
75	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
76	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
77	 * can be picked up once the integration is wired.
78	 */
79	async function provisionMailboxOnMailcow(mailbox: {
80	  id: string;
81	  address: string;
82	  quotaMB: number | null;
83	  subscription: { domainName: string };
84	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
85	  if (!mailcowConfigured()) return "PROVISIONING";
86	
87	  const [localPart] = mailbox.address.split("@");
88	  const domain = mailbox.subscription.domainName;
89	  const quotaMB = mailbox.quotaMB ?? 1024;
90	
91	  try {
92	    // Ensure the mail domain exists before adding the mailbox.
93	    if (!(await mcDomainExists(domain))) {
94	      // A concurrent create or pre-existing domain can still error here; ignore
95	      // and let the mailbox add be the real signal.
96	      await mcCreateDomain(domain).catch(() => {});
97	    }
98	
99	    const password = randomBytes(18).toString("base64url");
100	    await mcCreateMailbox({
101	      localPart,
102	      domain,
103	      name: mailbox.address,
104	      password,
105	      quotaMB,
106	    });
107	
108	    await db.mailbox.update({
109	      where: { id: mailbox.id },
110	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
111	    });
112	    return "ACTIVE";
113	  } catch (e) {
114	    await db.mailbox
115	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
116	      .catch(() => {});
117	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
118	    return "FAILED";
119	  }
120	}
121	
122	// ---------- Admin CRUD (billing area) ----------
123	
124	const planSchema = z.object({
125	  id: z.string().optional(),
126	  name: z.string().min(2).max(80),
127	  mailboxes: z.coerce.number().int().min(1).max(100000),
128	  storageGB: z.coerce.number().int().min(1).max(100000),
129	  priceCents: z.coerce.number().int().min(0).max(100000000),
130	  termMonths: z.coerce.number().int().min(1).max(36),
131	  sortOrder: z.coerce.number().int().min(0).max(100000),
132	});
133	
134	/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
135	export async function adminSaveEmailPlan(
136	  prev: Result | undefined,
137	  formData: FormData,
138	): Promise<Result> {
139	  const admin = await requireArea("billing");
140	
141	  const parsed = planSchema.safeParse({
142	    id: formData.get("id") || undefined,
143	    name: formData.get("name"),
144	    mailboxes: formData.get("mailboxes"),
145	    storageGB: formData.get("storageGB"),
146	    priceCents: formData.get("priceCents"),
147	    termMonths: formData.get("termMonths"),
148	    sortOrder: formData.get("sortOrder") ?? 0,
149	  });
150	  if (!parsed.success) {
151	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
152	  }
153	  const d = parsed.data;
154	  const active = formData.get("active") === "on";
155	
156	  const data = {
157	    name: d.name.trim(),
158	    mailboxes: d.mailboxes,
159	    storageGB: d.storageGB,
160	    priceCents: d.priceCents,
161	    termMonths: d.termMonths,
162	    active,
163	    sortOrder: d.sortOrder,
164	  };
165	
166	  if (d.id) {
167	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
168	    if (!existing) return { error: "Tier not found." };
169	    await db.emailPlan.update({ where: { id: d.id }, data });
170	  } else {
171	    await db.emailPlan.create({ data });
172	  }
173	
174	  await db.auditLog.create({
175	    data: {
176	      userId: admin.id,
177	      action: d.id ? "emailplan.update" : "emailplan.create",
178	      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
179	    },
180	  });
181	  revalidatePath("/admin/email-plans");
182	  return { ok: true };
183	}
184	
185	/** Flip a tier's active flag. */
186	export async function adminToggleEmailPlan(id: string): Promise<void> {
187	  const admin = await requireArea("billing");
188	  const plan = await db.emailPlan.findUnique({ where: { id } });
189	  if (!plan) return;
190	  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
191	  await db.auditLog.create({
192	    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
193	  });
194	  revalidatePath("/admin/email-plans");
195	}
196	
197	/** Delete a tier. Refused while subscriptions reference it. */
198	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
199	  const admin = await requireArea("billing");
200	  const plan = await db.emailPlan.findUnique({
201	    where: { id },
202	    include: { _count: { select: { subscriptions: true } } },
203	  });
204	  if (!plan) return { error: "Tier not found." };
205	  if (plan._count.subscriptions > 0) {
206	    return {
207	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
208	    };
209	  }
210	  await db.emailPlan.delete({ where: { id } });
211	  await db.auditLog.create({
212	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
213	  });
214	  revalidatePath("/admin/email-plans");
215	  return { ok: true };
216	}
217	
218	// ---------- Customer ordering ----------
219	
220	/**
221	 * Subscribe one of the caller's registered domains to an email plan. Validates
222	 * domain ownership + plan availability, then atomically debits the wallet and
223	 * creates the EmailSubscription with an expiry set from the plan term.
224	 *
225	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
226	 * provisioned with a mail provider yet — that integration is pending, and the
227	 * UI surfaces every mailbox as "provisioning" until it lands.
228	 */
229	export async function orderEmailHosting(
230	  domainName: string,
231	  emailPlanId: string,
232	): Promise<Result> {
233	  const user = await requireUser();
234	
235	  const name = String(domainName ?? "")
236	    .trim()
237	    .toLowerCase()
238	    .replace(/\.$/, "");
239	  if (!name) return { error: "Enter a domain." };
240	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
241	
242	  // Is the domain registered inside Nxeon? If so we control its DNS and can
243	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
244	  // verified via DNS before mail flows.
245	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
246	  const external = !inAccount;
247	
248	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
249	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
250	
251	  // One subscription per domain — refuse a duplicate.
252	  const dupe = await db.emailSubscription.findFirst({
253	    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
254	  });
255	  if (dupe) return { error: "This domain already has an email subscription." };
256	
257	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
258	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
259	  // strikethrough shown on the pricing page is the real renewal price and this
260	  // discounted value is the real first-term price — displayed === charged.
261	  const promo = currentPromo(new Date());
262	  const chargeCents = promoPriceCents(plan.priceCents, promo);
263	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
264	  if (user.balanceCents < chargeCents) {
265	    return { error: "Insufficient balance. Top up your wallet first." };
266	  }
267	
268	  try {
269	    await db.$transaction(async (tx) => {
270	      await debitWallet(tx, user.id, chargeCents);
271	      await tx.walletTransaction.create({
272	        data: {
273	          userId: user.id,
274	          amountCents: -chargeCents,
275	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
276	        },
277	      });
278	      await tx.emailSubscription.create({
279	        data: {
280	          userId: user.id,
281	          domainName: name,
282	          emailPlanId: plan.id,
283	          status: "ACTIVE",
284	          autoRenew: true,
285	          expiresAt: addMonths(new Date(), plan.termMonths),
286	          // In-account domains: we control DNS, so treat as verified now. External
287	          // domains: not verified until the customer publishes DNS + we confirm it.
288	          external,
289	          verified: !external,
290	          verifiedAt: external ? null : new Date(),
291	          verifyToken: external ? randomBytes(24).toString("hex") : null,
292	        },
293	      });
294	    });
295	  } catch (e) {
296	    if (e instanceof InsufficientBalanceError) {
297	      return { error: "Insufficient balance. Top up your wallet first." };
298	    }
299	    throw e;
300	  }
301	
302	  await db.auditLog.create({
303	    data: {
304	      userId: user.id,
305	      action: "emailhosting.order",
306	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
307	    },
308	  });
309	  revalidatePath("/dashboard/email");
310	  return { ok: true };
311	}
312	
313	// ---------- External-domain DNS setup + verification ----------
314	
315	/**
316	 * Return the DNS records a customer must publish at their registrar for an
317	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
318	 * ownership-verification record. Ownership-checked (caller must own the sub).
319	 *
320	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
321	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
322	 * note is returned so the panel still renders.
323	 */
324	export async function getEmailDnsRecords(
325	  subscriptionId: string,
326	): Promise<{
327	  error?: string;
328	  records?: DnsRecord[];
329	  verified?: boolean;
330	  external?: boolean;
331	  cloudflareConnected?: boolean;
332	}> {
333	  const user = await requireUser();
334	
335	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
336	  if (!sub) return { error: "Subscription not found." };
337	  if (sub.userId !== user.id) return { error: "Not your subscription." };
338	
339	  const domain = sub.domainName;
340	
341	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
342	  let dkimTxt = sub.dkimRecord ?? null;
343	  if (!dkimTxt && mailcowConfigured()) {
344	    try {
345	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
346	      if (!(await mcDomainExists(domain))) {
347	        await mcCreateDomain(domain).catch(() => {});
348	      }
349	      dkimTxt = await mcGetDkim(domain);
350	      if (dkimTxt) {
351	        await db.emailSubscription
352	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
353	          .catch(() => {});
354	      }
355	    } catch (e) {
356	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
357	    }
358	  }
359	
360	  const records: DnsRecord[] = [
361	    {
362	      type: "TXT",
363	      label: "Ownership verification",
364	      host: `_nxeon-verify.${domain}`,
365	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
366	      note: "Proves you control this domain. Required before mail is enabled.",
367	    },
368	    {
369	      type: "MX",
370	      label: "Mail routing (MX)",
371	      host: domain,
372	      value: MAIL_HOST,
373	      priority: MAIL_MX_PRIORITY,
374	    },
375	    {
376	      type: "TXT",
377	      label: "SPF",
378	      host: domain,
379	      value: SPF_VALUE,
380	      note: "Authorizes the Nxeon mail server to send for your domain.",
381	    },
382	    {
383	      type: "TXT",
384	      label: "DKIM",
385	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
386	      value: dkimTxt ?? "",
387	      note: dkimTxt
388	        ? undefined
389	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
390	    },
391	    {
392	      type: "TXT",
393	      label: "DMARC",
394	      host: `_dmarc.${domain}`,
395	      value: DMARC_VALUE,
396	      note: "Reporting policy for messages that fail SPF/DKIM.",
397	    },
398	  ];
399	
400	  return {
401	    records,
402	    verified: sub.verified,
