408	/**
409	 * Verify that an EXTERNAL domain's owner has published our verification record.
410	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
411	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
412	 * corroboration. The result is derived entirely server-side from live DNS —
413	 * client input never decides the outcome. Rate-limited per user + subscription.
414	 */
415	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
416	  const user = await requireUser();
417	
418	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
419	  if (!sub) return { error: "Subscription not found." };
420	  if (sub.userId !== user.id) return { error: "Not your subscription." };
421	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
422	  if (sub.verified) return { ok: true };
423	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
424	
425	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
426	    max: 6,
427	    windowMs: 60_000,
428	  });
429	  if (!rl.ok) {
430	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
431	  }
432	
433	  const domain = sub.domainName;
434	  const expected = `nxeon-verify=${sub.verifyToken}`;
435	
436	  // Primary signal: the verification TXT record must contain our exact token.
437	  let tokenFound = false;
438	  try {
439	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
440	    // Each record may be split into multiple strings — join per-record chunks.
441	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
442	  } catch {
443	    tokenFound = false;
444	  }
445	
446	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
447	  let mxOk = false;
448	  try {
449	    const mx = await resolveMx(domain);
450	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
451	  } catch {
452	    mxOk = false;
453	  }
454	
455	  if (!tokenFound) {
456	    return {
457	      error: mxOk
458	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
459	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
460	    };
461	  }
462	
463	  await db.emailSubscription.update({
464	    where: { id: sub.id },
465	    data: { verified: true, verifiedAt: new Date() },
466	  });
467	
468	  await db.auditLog.create({
469	    data: {
470	      userId: user.id,
471	      action: "emailhosting.verify",
472	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
473	    },
474	  });
475	  revalidatePath("/dashboard/email");
476	  return { ok: true };
477	}
