482	/**
483	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
484	 * quota and address uniqueness within the subscription, records the intended
485	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
486	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
487	 */
488	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
489	  const user = await requireUser();
490	
491	  const sub = await db.emailSubscription.findUnique({
492	    where: { id: subscriptionId },
493	    include: { emailPlan: true, mailboxes: true },
494	  });
495	  if (!sub) return { error: "Subscription not found." };
496	  if (sub.userId !== user.id) return { error: "Not your subscription." };
497	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
498	
499	  const local = String(localPart ?? "").trim().toLowerCase();
500	  if (!localPartRe.test(local) || local.length > 64) {
501	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
502	  }
503	
504	  const address = `${local}@${sub.domainName}`;
505	
506	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
507	    return {
508	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
509	    };
510	  }
511	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
512	    return { error: "That address already exists." };
513	  }
514	
515	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
516	  const quotaMB = sub.emailPlan.storageGB * 1024;
517	
518	  const mailbox = await db.mailbox.create({
519	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
520	  });
521	
522	  await db.auditLog.create({
523	    data: { userId: user.id, action: "mailbox.add", detail: address },
524	  });
525	
526	  // Additive, failure-tolerant provisioning — never throws out of the flow.
527	  await provisionMailboxOnMailcow({
528	    id: mailbox.id,
529	    address: mailbox.address,
530	    quotaMB,
531	    subscription: { domainName: sub.domainName },
532	  });
533	
534	  revalidatePath("/dashboard/email");
535	  return { ok: true };
536	}
