723	/**
724	 * Store a customer's Cloudflare API token (encrypted) so we can create their
725	 * mail DNS records for them. The token is verified against Cloudflare before it
726	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
727	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
728	 */
729	export async function saveCloudflareToken(token: string): Promise<Result> {
730	  const user = await requireUser();
731	
732	  const t = String(token ?? "").trim();
733	  if (!t) return { error: "Paste your Cloudflare API token." };
734	  if (t.length < 20 || t.length > 200) {
735	    return { error: "That doesn't look like a Cloudflare API token." };
736	  }
737	
738	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
739	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
740	
741	  let valid = false;
742	  try {
743	    valid = await cfVerifyToken(t);
744	  } catch (e) {
745	    console.warn("[cloudflare] token verify failed:", e);
746	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
747	  }
748	  if (!valid) {
749	    return {
750	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
751	    };
752	  }
753	
754	  await db.user.update({
755	    where: { id: user.id },
756	    data: { cloudflareTokenEnc: encryptSecret(t) },
757	  });
758	  await db.auditLog.create({
759	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
760	  });
761	  revalidatePath("/dashboard/email");
762	  return { ok: true };
763	}
