765	/**
766	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
767	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
768	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
769	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
770	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
771	 * gracefully with clear messages for invalid token / zone-not-found.
772	 */
773	export async function autoCreateEmailDns(
774	  subscriptionId: string,
775	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
776	  const user = await requireUser();
777	
778	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
779	  if (!sub) return { error: "Subscription not found." };
780	  if (sub.userId !== user.id) return { error: "Not your subscription." };
781	  if (!sub.external) {
782	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
783	  }
784	
785	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
786	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
787	
788	  const token = decryptSecret(user.cloudflareTokenEnc);
789	  if (!token) {
790	    return { error: "Connect your Cloudflare account first (paste an API token above)." };
791	  }
792	
793	  // Same record set the customer would otherwise publish by hand.
794	  const dns = await getEmailDnsRecords(subscriptionId);
795	  if (dns.error) return { error: dns.error };
796	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
797	  if (records.length === 0) {
798	    return { error: "No DNS records to create yet — try again in a moment." };
799	  }
800	
801	  let zoneId: string | null;
802	  try {
803	    zoneId = await cfFindZoneId(token, sub.domainName);
804	  } catch (e) {
805	    if (e instanceof CloudflareError) {
806	      return { error: `Cloudflare error: ${e.message}` };
807	    }
808	    throw e;
809	  }
810	  if (!zoneId) {
811	    return {
812	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
813	    };
814	  }
815	
816	  let created: string[];
817	  try {
818	    const results = await cfUpsertRecords(
819	      token,
820	      zoneId,
821	      records.map((r) => ({
822	        type: r.type,
823	        name: r.host,
824	        content: r.value,
825	        priority: r.priority,
826	      })),
827	    );
828	    created = results.map((res) => {
829	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
830	      return `${label} (${res.type}, ${res.action})`;
831	    });
832	  } catch (e) {
833	    if (e instanceof CloudflareError) {
834	      return {
835	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
836	      };
837	    }
838	    throw e;
839	  }
840	
841	  await db.auditLog.create({
842	    data: {
843	      userId: user.id,
844	      action: "cloudflare.autodns",
845	      detail: `${sub.domainName} — ${created.length} record(s)`,
846	    },
847	  });
848	  revalidatePath("/dashboard/email");
849	  return { ok: true, created };
850	}
