3	/**
4	 * Control panel — Websites & PHP.
5	 *
6	 * Add a website (nginx server block + docroot under /var/www/<domain>), pick a
7	 * PHP-FPM version, enable/disable, one-click Let's Encrypt SSL, and subdomains.
8	 * List/edit/delete. Every op is ownership-checked + rate-limited and respects
9	 * the "no panel work while a lifecycle job is in flight / server not running"
10	 * invariant. The real SSH work runs in worker/websites.ts (sandbox-gated); the
11	 * lists here are served straight from the Website table.
12	 */
13	import { revalidatePath } from "next/cache";
