20	type Result = { ok: true } | { ok: false; error: string };
21	type CreateResult = { ok: true; id: string } | { ok: false; error: string };
22	
23	/** Job types that must not overlap with panel work (lifecycle / destructive). */
24	const EXCLUSIVE_JOBS = [
25	  "PROVISION",
26	  "REINSTALL",
27	  "DELETE",
28	  "RESIZE",
29	  "SUSPEND",
30	  "UNSUSPEND",
31	  "SNAPSHOT_ROLLBACK",
