35	async function ownedServer(serverId: string) {
36	  const user = await requireUser();
37	  const server = await db.server.findUnique({
38	    where: { id: serverId },
39	    select: { id: true, userId: true, status: true, hostname: true },
40	  });
41	  if (!server) throw new Error("Not found");
42	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
43	  return { user, server };
44	}
