57	function throttle(userId: string, op: string, max: number): string | null {
58	  const rl = checkRateLimit(`cpanel:web:${op}:${userId}`, { max, windowMs: 60_000 });
59	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
