/**
 * Dependency-free, in-memory sliding-window rate limiter.
 *
 * Suitable for single-process app-level throttling (login attempts, etc).
 * State lives in a module-level Map; on a horizontally-scaled deployment each
 * instance limits independently — acceptable for auth-abuse mitigation. A
 * background sweep prunes empty buckets so the Map does not grow unbounded.
 */

type Bucket = number[]; // sorted-ish list of hit timestamps (ms)

const buckets = new Map<string, Bucket>();

// Persist the Map across HMR / route reloads in dev.
const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;

export type RateLimitOptions = { max: number; windowMs: number };
export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };

/**
 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
 * When `ok` is false the caller should reject and surface `retryAfterSec`.
 */
export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
  const now = Date.now();
  sweep(now);
  const cutoff = now - windowMs;
  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);

  if (hits.length >= max) {
    const oldest = hits[0];
    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
    store.set(key, hits); // persist the pruned window
    return { ok: false, retryAfterSec, remaining: 0 };
  }

  hits.push(now);
  store.set(key, hits);
  return { ok: true, retryAfterSec: 0, remaining: max - hits.length };
}

/** Clear the window for a key (e.g. after a successful login). */
export function resetRateLimit(key: string): void {
  store.delete(key);
}

/**
 * Preset for login throttling: 5 attempts per 15 minutes per identifier.
 * Pass a stable identifier such as `${email}:${ip}`.
 */
export function loginRateLimit(identifier: string): RateLimitResult {
  return checkRateLimit(`login:${identifier}`, { max: 5, windowMs: 15 * 60 * 1000 });
}

// Opportunistic sweep of fully-expired buckets (runs at most once/min, no timer).
let lastSweep = 0;
function sweep(now: number) {
  if (now - lastSweep < 60_000) return;
  lastSweep = now;
  const maxWindow = 15 * 60 * 1000;
  for (const [key, hits] of store) {
    if (hits.length === 0 || hits[hits.length - 1] < now - maxWindow) store.delete(key);
  }
}

