// What the customer was doing when they clicked "Connect Cloudflare".
//
// Plain server-side module shared by the OAuth start/callback routes and the
// client button. The intent rides in an httpOnly cookie (NOT the URL) alongside
// the CSRF `state` and the PKCE verifier, so the callback can finish the job the
// customer actually asked for — "log in with Cloudflare → records added", no
// extra clicks — and land them back on the page they started from.
//
// Everything here is validated: the callback re-checks ownership through the
// normal action paths before touching DNS, and `next` is forced to a relative
// /dashboard path so the flow can never be turned into an open redirect.

export type CfConnectIntent =
  | { kind: "settings" }
  /** Business Email external-domain DNS for an EmailSubscription. */
  | { kind: "email"; id: string }
  /** Point a control-panel Website's hostname at its server. */
  | { kind: "website"; id: string }
  /** Post-migration: point one hostname at the migration's target server. */
  | { kind: "migration"; id: string; host?: string };

const KINDS = ["settings", "email", "website", "migration"] as const;

/** cuid-ish id guard — ids only ever come from our own rows. */
const ID_RE = /^[A-Za-z0-9_-]{6,64}$/;

/**
 * Build an intent from raw query params. Anything unrecognised collapses to
 * `{ kind: "settings" }` (connect only, no auto-action) rather than erroring.
 */
export function parseIntent(params: {
  intent?: string | null;
  id?: string | null;
  host?: string | null;
}): CfConnectIntent {
  const kind = String(params.intent ?? "").trim();
  const id = String(params.id ?? "").trim();
  if (!(KINDS as readonly string[]).includes(kind)) return { kind: "settings" };
  if (kind === "settings") return { kind: "settings" };
  if (!ID_RE.test(id)) return { kind: "settings" };
  if (kind === "migration") {
    const host = String(params.host ?? "").trim().toLowerCase();
    return { kind: "migration", id, ...(host ? { host } : {}) };
  }
  return { kind: kind as "email" | "website", id };
}

/**
 * Force a return path to a safe, same-origin dashboard route. Rejects absolute
 * URLs, protocol-relative paths and anything outside /dashboard.
 */
export function safeNext(next: string | null | undefined, fallback = "/dashboard/settings"): string {
  const raw = String(next ?? "").trim();
  if (!raw.startsWith("/") || raw.startsWith("//")) return fallback;
  if (!/^\/dashboard(\/|$|\?)/.test(raw)) return fallback;
  if (raw.includes("\\") || raw.includes("\n")) return fallback;
  return raw.slice(0, 300);
}

/** Append our result flags to a dashboard path, preserving any existing query. */
export function withResult(next: string, params: Record<string, string>): string {
  const [path, query = ""] = next.split("?");
  const sp = new URLSearchParams(query);
  for (const [k, v] of Object.entries(params)) sp.set(k, v);
  const qs = sp.toString();
  return qs ? `${path}?${qs}` : path;
}

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { SANDBOX } from "@/lib/sandbox";
import {
  cfAuthorizeUrl,
  cloudflareOauthConfigured,
  packCreds,
  pkceChallenge,
  randomUrlSafe,
} from "@/lib/cloudflare-oauth";
import { parseIntent, safeNext, withResult } from "@/lib/cloudflare-connect-intent";
import { db } from "@/lib/db";
import { runConnectIntent } from "@/lib/cloudflare-intent-run";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "").replace(/\/$/, "");

/**
 * Step 1 of "Connect Cloudflare": start the Authorization Code flow.
 *
 * Requires a signed-in user, mints a CSRF `state` + PKCE verifier (S256) and
 * stashes them — with the intent and the return path — in a short-lived httpOnly
 * cookie, then redirects to Cloudflare's consent screen. Nothing sensitive rides
 * in the URL; the cookie is the only thing the callback trusts.
 */
export async function GET(req: NextRequest) {
  let user;
  try {
    user = await requireUser();
  } catch {
    return NextResponse.redirect(`${base()}/login`);
  }

  const sp = req.nextUrl.searchParams;
  const intent = parseIntent({ intent: sp.get("intent"), id: sp.get("id"), host: sp.get("host") });
  const next = safeNext(sp.get("next"));

  const rl = checkRateLimit(`cf-oauth-start:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.redirect(
      `${base()}${withResult(next, { cf: "error", cfmsg: `Too many attempts — try again in ${rl.retryAfterSec}s.` })}`,
    );
  }

  // SANDBOX: never leave the app. Store a synthetic connection and run the
  // auto-add straight away so staging exercises the whole "connect → records
  // added" path without touching Cloudflare.
  if (SANDBOX) {
    await db.user.update({
      where: { id: user.id },
      data: {
        cloudflareTokenEnc: packCreds({
          accessToken: `sandbox-${randomUrlSafe(12)}`,
          refreshToken: `sandbox-${randomUrlSafe(12)}`,
          expiresAt: Date.now() + 3600_000,
          scope: "sandbox",
        }),
      },
    });
    await db.auditLog
      .create({ data: { userId: user.id, action: "cloudflare.connect", detail: "OAuth (sandbox)" } })
      .catch(() => {});
    const outcome = await runConnectIntent(intent);
    return NextResponse.redirect(`${base()}${withResult(next, { cf: "connected", ...outcome.params })}`);
  }

  if (!cloudflareOauthConfigured()) {
    return NextResponse.redirect(
      `${base()}${withResult(next, {
        cf: "error",
        cfmsg: "Cloudflare sign-in isn't set up on this server yet — paste an API token instead.",
      })}`,
    );
  }

  const state = randomUrlSafe(24);
  const verifier = randomUrlSafe(32);
  const authUrl = cfAuthorizeUrl({ state, codeChallenge: pkceChallenge(verifier) });

  const res = NextResponse.redirect(authUrl);
  res.cookies.set({
    name: "nx_cf_oauth",
    value: JSON.stringify({ state, verifier, next, intent, uid: user.id }),
    httpOnly: true,
    sameSite: "lax", // must survive the top-level redirect back from Cloudflare
    secure: (process.env.APP_URL ?? "").startsWith("https://"),
    path: "/api/integrations/cloudflare",
    maxAge: 600, // 10 minutes to complete consent
  });
  return res;
}

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { cfExchangeCode, packCreds } from "@/lib/cloudflare-oauth";
import { parseIntent, safeNext, withResult, type CfConnectIntent } from "@/lib/cloudflare-connect-intent";
import { runConnectIntent } from "@/lib/cloudflare-intent-run";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "").replace(/\/$/, "");

type Stash = { state?: string; verifier?: string; next?: string; intent?: unknown; uid?: string };

/** Clear the one-shot OAuth cookie on every exit path. */
function finish(res: NextResponse): NextResponse {
  res.cookies.set({
    name: "nx_cf_oauth",
    value: "",
    httpOnly: true,
    path: "/api/integrations/cloudflare",
    maxAge: 0,
  });
  return res;
}

/**
 * Step 2 of "Connect Cloudflare": the OAuth redirect target.
 *
 * Verifies the CSRF `state` against the httpOnly cookie, exchanges the code (with
 * the PKCE verifier) for credentials, stores them encrypted in the existing
 * `User.cloudflareTokenEnc` column, then immediately runs the action the customer
 * started — so they land back on their page with the DNS records already
 * published. No token is ever logged or put in a URL.
 */
export async function GET(req: NextRequest) {
  let user;
  try {
    user = await requireUser();
  } catch {
    return finish(NextResponse.redirect(`${base()}/login`));
  }

  const raw = req.cookies.get("nx_cf_oauth")?.value;
  let stash: Stash = {};
  try {
    stash = raw ? (JSON.parse(raw) as Stash) : {};
  } catch {
    stash = {};
  }

  const next = safeNext(stash.next);
  const fail = (msg: string) =>
    finish(NextResponse.redirect(`${base()}${withResult(next, { cf: "error", cfmsg: msg })}`));

  const sp = req.nextUrl.searchParams;

  // The customer declined on Cloudflare's consent screen (or Cloudflare errored).
  const oauthError = sp.get("error");
  if (oauthError) {
    return fail(
      oauthError === "access_denied"
        ? "Cloudflare connection cancelled."
        : `Cloudflare returned an error (${oauthError.slice(0, 60)}).`,
    );
  }

  // CSRF: the state must match the cookie minted by /start for THIS user.
  const state = sp.get("state") ?? "";
  if (!stash.state || !stash.verifier || !state || state !== stash.state) {
    return fail("That Cloudflare sign-in link expired or didn't match. Please try connecting again.");
  }
  if (stash.uid && stash.uid !== user.id) {
    return fail("That Cloudflare sign-in was started by a different account. Please try again.");
  }

  const code = sp.get("code") ?? "";
  if (!code) return fail("Cloudflare didn't return an authorization code. Please try connecting again.");

  const exchanged = await cfExchangeCode({ code, codeVerifier: stash.verifier });
  if (!exchanged.creds) {
    return fail(exchanged.error ?? "Couldn't complete the Cloudflare connection. Please try again.");
  }

  await db.user.update({
    where: { id: user.id },
    data: { cloudflareTokenEnc: packCreds(exchanged.creds) },
  });
  await db.auditLog
    .create({ data: { userId: user.id, action: "cloudflare.connect", detail: "OAuth authorised" } })
    .catch(() => {});

  // "Connect → records added": finish the job they clicked from, with no extra step.
  const intent: CfConnectIntent =
    stash.intent && typeof stash.intent === "object"
      ? parseIntent({
          intent: (stash.intent as { kind?: string }).kind ?? null,
          id: (stash.intent as { id?: string }).id ?? null,
          host: (stash.intent as { host?: string }).host ?? null,
        })
      : { kind: "settings" };

  const outcome = await runConnectIntent(intent);
  return finish(
    NextResponse.redirect(`${base()}${withResult(next, { cf: "connected", ...outcome.params })}`),
  );
}

// "Connect Cloudflare → records added" — run the job the customer clicked from,
// immediately after the OAuth callback stores their credentials.
//
// Plain server-side module. Every branch calls the SAME ownership-checked,
// rate-limited server action the button would have called, so connecting can
// never do more than the customer could do themselves; the intent only decides
// WHICH of their own records we publish. Result flags are folded into the
// redirect back to the page they started on.

import type { CfConnectIntent } from "./cloudflare-connect-intent";
import { autoCreateEmailDns } from "./actions-email-hosting";
import { pointWebsiteDns } from "./actions-websites";
import { pointMigrationDns } from "./actions-migrate";

export type IntentOutcome = { params: Record<string, string> };

/** Trim a message to something safe to carry in a redirect query string. */
function msg(s: string): string {
  return s.replace(/\s+/g, " ").trim().slice(0, 220);
}

/**
 * Execute the post-connect action for an intent. Never throws — any failure
 * becomes a `cfdns=error` flag with a friendly message, so the customer always
 * lands back on their page with an explanation rather than a stack trace.
 */
export async function runConnectIntent(intent: CfConnectIntent): Promise<IntentOutcome> {
  try {
    switch (intent.kind) {
      case "email": {
        const res = await autoCreateEmailDns(intent.id);
        if (res.error) return { params: { cfdns: "error", cfmsg: msg(res.error) } };
        const n = res.created?.length ?? 0;
        return {
          params: {
            cfdns: "ok",
            cfmsg: msg(`Created ${n} mail DNS record${n === 1 ? "" : "s"} in Cloudflare.`),
          },
        };
      }
      case "website": {
        const res = await pointWebsiteDns(intent.id);
        if (!res.ok) return { params: { cfdns: "error", cfmsg: msg(res.error) } };
        return { params: { cfdns: "ok", cfmsg: msg(res.message) } };
      }
      case "migration": {
        if (!intent.host) return { params: {} };
        const res = await pointMigrationDns(intent.id, intent.host);
        if (!res.ok) return { params: { cfdns: "error", cfmsg: msg(res.error) } };
        return { params: { cfdns: "ok", cfmsg: msg(res.message) } };
      }
      default:
        return { params: {} };
    }
  } catch {
    return {
      params: {
        cfdns: "error",
        cfmsg: "Cloudflare is connected, but we couldn't add the record automatically — try the button again.",
      },
    };
  }
}

"use server";

/**
 * Cloudflare as an ACCOUNT-LEVEL integration.
 *
 * The connection used to be email-only (a token pasted inside the Business Email
 * DNS panel). It is now a first-class integration surfaced in Settings and reused
 * by every DNS surface: mail records, "point this website at my server", and the
 * post-migration domain cutover.
 *
 * Preferred path is OAuth ("Connect Cloudflare" → consent → we hold short-lived
 * credentials with a refresh token). The legacy paste-an-API-token path is kept
 * as an advanced fallback and still works, including for anyone who connected
 * before OAuth existed — `readStoredCloudflare` sniffs which shape is stored.
 *
 * NO SCHEMA CHANGE: both shapes live encrypted in `User.cloudflareTokenEnc`.
 * The token/credentials are never logged, never returned to the client.
 */

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { encryptSecret } from "./crypto-box";
import { SANDBOX } from "./sandbox";
import { saveCloudflareToken } from "./actions-email-hosting";
import {
  CF_SCOPE_SUMMARY,
  cfRedirectUri,
  cfRevoke,
  cloudflareOauthConfigured,
  readStoredCloudflare,
} from "./cloudflare-oauth";

type Result = { ok?: boolean; error?: string };

export type CloudflareStatus = {
  /** Something usable is stored (OAuth credentials or a legacy API token). */
  connected: boolean;
  /** How they connected — drives the wording in Settings. */
  kind: "oauth" | "token" | null;
  /** Is the "Connect Cloudflare" button available in this environment? */
  oauthAvailable: boolean;
  /** Plain-English summary of the access we request. */
  scopeSummary: string;
};

/**
 * Connection state for the current user. Safe to call from any surface — it
 * never returns the credentials themselves, only whether they exist.
 */
export async function getCloudflareStatus(): Promise<CloudflareStatus> {
  const user = await requireUser();
  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
  return {
    connected: stored !== null,
    kind: stored?.kind ?? null,
    // In sandbox the button works (synthetic connect) without registered creds.
    oauthAvailable: SANDBOX || cloudflareOauthConfigured(),
    scopeSummary: CF_SCOPE_SUMMARY,
  };
}

/**
 * Advanced fallback: store a pasted Cloudflare API token. Delegates to the
 * existing verify-then-store path (`saveCloudflareToken`) so there is exactly one
 * implementation of "check the token is real before we keep it", then revalidates
 * the surfaces that show connection state.
 */
export async function connectCloudflareToken(token: string): Promise<Result> {
  // SANDBOX has no network, so Cloudflare's verify call can't run. Accept the
  // pasted value as-is (encrypted) so staging can exercise the whole flow.
  if (SANDBOX) {
    const user = await requireUser();
    const t = String(token ?? "").trim();
    if (t.length < 20 || t.length > 200) {
      return { error: "That doesn't look like a Cloudflare API token." };
    }
    const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
    if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
    await db.user.update({ where: { id: user.id }, data: { cloudflareTokenEnc: encryptSecret(t) } });
    revalidatePath("/dashboard/settings");
    return { ok: true };
  }

  const res = await saveCloudflareToken(token);
  if (res.ok) revalidatePath("/dashboard/settings");
  return res;
}

/**
 * Disconnect Cloudflare: clear the stored credentials. For an OAuth connection
 * we also make a best-effort revoke call at Cloudflare so their side drops too
 * (a failed remote revoke never blocks the local disconnect — clearing the blob
 * is what actually stops us using it).
 */
export async function disconnectCloudflare(): Promise<Result> {
  const user = await requireUser();

  const rl = checkRateLimit(`cf-disconnect:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
  if (!stored) return { ok: true };

  if (stored.kind === "oauth") {
    await cfRevoke(stored.creds.refreshToken || stored.creds.accessToken);
  }

  await db.user.update({ where: { id: user.id }, data: { cloudflareTokenEnc: null } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "cloudflare.disconnect",
      detail: stored.kind === "oauth" ? "OAuth connection revoked" : "API token removed",
    },
  });

  revalidatePath("/dashboard/settings");
  revalidatePath("/dashboard/email");
  return { ok: true };
}

/**
 * The exact redirect URI that must be registered on the Cloudflare OAuth client.
 * Surfaced in Settings only when OAuth isn't configured yet, so the operator can
 * see what to register. Contains no secrets.
 */
export async function cloudflareRedirectUri(): Promise<string> {
  await requireUser();
  return cfRedirectUri();
}

