cd /opt/nxeon && cat >> lib/actions-migrate.ts <<'EOF'

// ---- Post-migration DNS cutover --------------------------------------------

/**
 * A domain we can offer to repoint after a migration, plus where we got it from
 * (shown in the UI so the customer knows why it's listed).
 */
export type DnsCandidate = {
  host: string;
  source: "registered" | "website" | "scan";
};

export type MigrationDnsInfo = {
  error?: string;
  targetIp?: string | null;
  targetName?: string | null;
  candidates?: DnsCandidate[];
  cloudflareConnected?: boolean;
};

/** Pull a hostname out of a path like `/var/www/example.com` / `/home/example.com`. */
function hostnameFromPath(path: string): string | null {
  const leaf = String(path ?? "").split("/").filter(Boolean).pop() ?? "";
  const h = leaf.toLowerCase().replace(/^www\./, "");
  return cleanHostname(h);
}

/**
 * Candidate domains to point at the migration's target server, cheapest source
 * first. Ownership-checked (the migration must be the caller's).
 *
 *   1. `Domain` rows — domains the customer registered with us.
 *   2. Websites already configured on the target server.
 *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
 *      — web-root folders are conventionally named after the vhost. The snapshot
 *      does not record nginx/apache `server_name` values, so this is a best-effort
 *      read of what was already captured; we never re-scan the source.
 */
export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
  const user = await requireUser();

  const m = await db.migration.findUnique({ where: { id: migrationId } });
  if (!m) return { error: "Migration not found." };
  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };

  const server = await db.server.findUnique({
    where: { id: m.serverId },
    select: { hostname: true, label: true, ipAddress: true, dedicatedIp: { select: { address: true } } },
  });

  const seen = new Set<string>();
  const candidates: DnsCandidate[] = [];
  const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
    const host = cleanHostname(raw ?? "");
    if (!host || seen.has(host)) return;
    seen.add(host);
    candidates.push({ host, source });
  };

  const domains = await db.domain.findMany({
    where: { userId: m.userId },
    select: { name: true },
    orderBy: { name: "asc" },
    take: 50,
  });
  for (const d of domains) push(d.name, "registered");

  const sites = await db.website.findMany({
    where: { serverId: m.serverId },
    select: { domain: true },
    take: 50,
  });
  for (const s of sites) push(s.domain, "website");

  // Only what the scan already stored — no new source-scanning here.
  const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
  for (const w of items.scan?.webRoots ?? []) {
    if (w?.path) push(hostnameFromPath(w.path), "scan");
  }

  return {
    targetIp: server?.dedicatedIp?.address ?? server?.ipAddress ?? null,
    targetName: server ? server.label || server.hostname : null,
    candidates: candidates.slice(0, 40),
    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
  };
}

/**
 * Point one hostname at the migration's TARGET server by upserting an A record in
 * the customer's Cloudflare zone — the last manual step of an otherwise one-click
 * migration.
 *
 * Guards: requireUser + migration ownership, rate-limited, and the hostname is
 * re-validated server-side (`cleanHostname` inside pointHostnameToIp) because
 * this one legitimately comes from customer input (the "enter a domain" box).
 * The record is DNS-only (proxied=false) so the name resolves to the server
 * itself and Let's Encrypt HTTP-01 validation can succeed there.
 */
export async function pointMigrationDns(
  migrationId: string,
  hostname: string
): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
  const user = await requireUser();

  const m = await db.migration.findUnique({ where: { id: migrationId } });
  if (!m) return { ok: false, error: "Migration not found." };
  if (m.userId !== user.id && user.role !== "ADMIN") return { ok: false, error: "Not your migration." };

  const rl = checkRateLimit(`migrate:dns:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { ok: false, error: `Too many requests — retry in ${rl.retryAfterSec}s.` };

  const server = await db.server.findUnique({
    where: { id: m.serverId },
    select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
  });
  const ip = server?.dedicatedIp?.address ?? server?.ipAddress ?? null;
  if (!ip) {
    return { ok: false, error: "Your new server doesn't have a public IP yet — try again shortly." };
  }

  const res = await pointHostnameToIp({
    user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
    hostname,
    ip,
  });
  if (!res.ok) return { ok: false, error: res.error };

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "migration.dns",
      detail: `${res.hostname} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
    },
  });

  return {
    ok: true,
    message: res.simulated
      ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). Nothing was sent to Cloudflare.`
      : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). It can take a few minutes for visitors to see the new server.`,
  };
}
