"use client";

import { useEffect, useState, useTransition, type ReactNode } from "react";
import { Badge } from "@/components/ui/primitives";
import {
  getCloudflareStatus,
  connectCloudflareToken,
  type CloudflareStatus,
} from "@/lib/actions-cloudflare";

/**
 * Shared "Connect Cloudflare" control, used by every DNS surface (Business Email
 * records, control-panel Websites, post-migration cutover, Settings).
 *
 * One button, no copy-pasting: it sends the customer to Cloudflare's own consent
 * screen and — because the intent rides along — the records they asked for are
 * created the moment they come back. Pasting an API token still works but is
 * demoted to an "Advanced" disclosure for people who prefer it (or whose account
 * predates the OAuth client being registered).
 */

export type CfIntentKind = "settings" | "email" | "website" | "migration";

/** Link to the OAuth start route, carrying what to do once connected. */
export function cloudflareStartHref(opts: {
  intent: CfIntentKind;
  id?: string;
  host?: string;
  next: string;
}): string {
  const sp = new URLSearchParams({ intent: opts.intent, next: opts.next });
  if (opts.id) sp.set("id", opts.id);
  if (opts.host) sp.set("host", opts.host);
  return `/api/integrations/cloudflare/start?${sp.toString()}`;
}

/**
 * Banner for the `?cf=` / `?cfdns=` flags the OAuth callback appends when it
 * lands the customer back on their page. Reads them from the URL on mount (no
 * useSearchParams, so no Suspense boundary needed) and tidies the URL afterwards.
 */
export function CloudflareResultBanner() {
  const [msg, setMsg] = useState<{ tone: "ok" | "error"; text: string } | null>(null);

  useEffect(() => {
    const sp = new URLSearchParams(window.location.search);
    const cf = sp.get("cf");
    const cfdns = sp.get("cfdns");
    const detail = sp.get("cfmsg");
    if (!cf && !cfdns) return;

    if (cf === "error") {
      setMsg({ tone: "error", text: detail || "Couldn't connect Cloudflare." });
    } else if (cfdns === "error") {
      setMsg({
        tone: "error",
        text: `Cloudflare connected, but the DNS record wasn't added: ${detail || "unknown error"}`,
      });
    } else if (cfdns === "ok") {
      setMsg({ tone: "ok", text: `Cloudflare connected. ${detail || "DNS records added."}` });
    } else if (cf === "connected") {
      setMsg({ tone: "ok", text: "Cloudflare connected." });
    }

    // Drop our flags from the address bar so a refresh doesn't re-show the banner.
    ["cf", "cfdns", "cfmsg"].forEach((k) => sp.delete(k));
    const qs = sp.toString();
    window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
  }, []);

  if (!msg) return null;
  return (
    <div
      className={`mb-4 rounded-xl border px-3 py-2 text-sm ${
        msg.tone === "ok"
          ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
          : "border-amber-500/30 bg-amber-500/10 text-amber-200"
      }`}
    >
      {msg.text}
    </div>
  );
}

/**
 * Connect state + connect controls. When connected it simply renders `children`
 * (the surface's own action, e.g. "Point DNS at this server"); when not, it shows
 * the Connect button and the advanced token fallback.
 */
export function CloudflareConnect({
  intent,
  id,
  host,
  next,
  connectedHint,
  onConnected,
  what,
  children,
  compact,
}: {
  intent: CfIntentKind;
  id?: string;
  host?: string;
  /** Dashboard path to return to after consent. */
  next: string;
  /** Optional first-paint value so the panel doesn't flicker. */
  connectedHint?: boolean;
  onConnected?: () => void;
  /** What we'll do once connected, e.g. "create these mail records". */
  what?: string;
  children?: ReactNode;
  compact?: boolean;
}) {
  const [status, setStatus] = useState<CloudflareStatus | null>(null);
  const [token, setToken] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [saving, startSave] = useTransition();

  useEffect(() => {
    let cancelled = false;
    getCloudflareStatus()
      .then((s) => {
        if (!cancelled) setStatus(s);
      })
      .catch(() => {
        /* leave the hint in place */
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const connected = status?.connected ?? connectedHint ?? false;
  const oauthAvailable = status?.oauthAvailable ?? true;

  function connectWithToken() {
    const t = token.trim();
    if (!t) {
      setError("Paste your Cloudflare API token.");
      return;
    }
    setError(null);
    startSave(async () => {
      const res = await connectCloudflareToken(t);
      if (res?.error) {
        setError(res.error);
        return;
      }
      setToken("");
      setStatus((s) => (s ? { ...s, connected: true, kind: "token" } : s));
      onConnected?.();
    });
  }

  if (connected) {
    return (
      <div className={compact ? "" : "space-y-2"}>
        {!compact && (
          <p className="text-xs text-emerald-300">
            Cloudflare is connected
            {status?.kind === "token" ? " (API token)" : ""}.
          </p>
        )}
        {children}
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
          {error}
        </div>
      )}

      {oauthAvailable ? (
        <>
          <a className="btn-primary inline-flex py-1.5 text-sm" href={cloudflareStartHref({ intent, id, host, next })}>
            Connect Cloudflare
          </a>
          <p className="text-xs text-slate-400">
            Sign in at Cloudflare and approve access — we only ask to{" "}
            {status?.scopeSummary ?? "read your zones and edit DNS records"}, and we only touch the
            records you ask us to.
            {what ? ` We'll ${what} as soon as you're back.` : ""}
          </p>
        </>
      ) : (
        <p className="text-xs text-slate-400">
          Cloudflare sign-in isn&apos;t set up on this server yet — paste an API token below instead.
        </p>
      )}

      <details className="group">
        <summary className="cursor-pointer text-xs text-slate-500 hover:text-slate-300">
          Advanced: paste an API token instead
        </summary>
        <div className="mt-2">
          <p className="text-xs text-slate-400">
            Create a token scoped to{" "}
            <span className="font-medium text-slate-200">Zone → DNS → Edit</span> (Cloudflare → My
            Profile → API Tokens → Create Token → Edit zone DNS). It&apos;s stored encrypted and used
            only to publish the records you ask for.
          </p>
          <div className="mt-2 flex flex-wrap items-end gap-2">
            <div className="min-w-0 flex-1">
              <label className="label">Cloudflare API token</label>
              <input
                className="input"
                type="password"
                value={token}
                onChange={(e) => setToken(e.target.value)}
                placeholder="Paste token"
                autoCapitalize="none"
                autoCorrect="off"
                spellCheck={false}
              />
            </div>
            <button className="btn-secondary py-1.5 text-sm" onClick={connectWithToken} disabled={saving}>
              {saving ? "Connecting…" : "Use token"}
            </button>
          </div>
        </div>
      </details>
    </div>
  );
}

