/** Where a candidate domain came from — shown so the list is self-explanatory. */
const CANDIDATE_SOURCE: Record<DnsCandidate["source"], string> = {
  registered: "registered with Nxeon",
  website: "website on this server",
  scan: "found on the old server",
};

/**
 * The last manual step of an otherwise one-click migration: moving DNS.
 *
 * Lists the domains we can already see (registered with us, websites on the new
 * server, and hostnames inferable from the migration's stored scan snapshot) and
 * points each at the new server's IP with one click, via the customer's
 * Cloudflare connection. Records are written DNS-only (not proxied) so the name
 * resolves to the server itself — that's what lets Let's Encrypt validate and
 * non-HTTP services keep working.
 */
function PostMigrationDns({ migrationId }: { migrationId: string }) {
  const [info, setInfo] = useState<MigrationDnsInfo | null>(null);
  const [manual, setManual] = useState("");
  const [busyHost, setBusyHost] = useState<string | null>(null);
  const [notes, setNotes] = useState<{ host: string; tone: "ok" | "error"; text: string }[]>([]);

  useEffect(() => {
    let cancelled = false;
    getMigrationDnsInfo(migrationId)
      .then((res) => {
        if (!cancelled) setInfo(res);
      })
      .catch(() => {
        if (!cancelled) setInfo({ error: "Couldn't load your domains right now." });
      });
    return () => {
      cancelled = true;
    };
  }, [migrationId]);

  async function point(host: string) {
    setBusyHost(host);
    try {
      const res = await pointMigrationDns(migrationId, host);
      setNotes((n) => [
        { host, tone: res.ok ? "ok" : "error", text: res.ok ? res.message : res.error },
        ...n.filter((x) => x.host !== host),
      ]);
      if (res.ok) setManual("");
    } finally {
      setBusyHost(null);
    }
  }

  const connected = info?.cloudflareConnected ?? false;
  const candidates = info?.candidates ?? [];
  const targetIp = info?.targetIp ?? null;
  const nextPath = "/dashboard/migrate";

  return (
    <div className="card border-sky-500/30">
      <h3 className="mb-1 font-semibold text-white">Point your domains at the new server</h3>
      <p className="mb-3 text-sm text-slate-400">
        Everything is copied across, but visitors still reach your old box until DNS moves. We can
        update the <span className="font-mono">A</span> record for each domain to{" "}
        {targetIp ? (
          <span className="font-mono text-slate-200">{targetIp}</span>
        ) : (
          "your new server's IP"
        )}{" "}
        in your Cloudflare zone. Records are created{" "}
        <span className="font-medium text-slate-200">DNS-only (no orange cloud)</span> so the name
        resolves straight to your server and SSL can be issued. Expect a few minutes before everyone
        sees the change — keep the old server up until then.
      </p>

      {info?.error && (
        <div className="mb-3 rounded-xl border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-300">
          {info.error}
        </div>
      )}

      {notes.map((n) => (
        <div
          key={n.host}
          className={`mb-2 rounded-xl border px-3 py-2 text-xs ${
            n.tone === "ok"
              ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
              : "border-red-500/30 bg-red-500/10 text-red-400"
          }`}
        >
          {n.text}
        </div>
      ))}

      {info && !connected && (
        <div className="mb-4">
          <CloudflareConnect
            intent="migration"
            id={migrationId}
            next={nextPath}
            connectedHint={false}
            onConnected={() => setInfo((i) => (i ? { ...i, cloudflareConnected: true } : i))}
            what="bring you straight back here"
          />
        </div>
      )}

      {info && candidates.length > 0 && (
        <ul className="divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
          {candidates.map((c) => (
            <li key={c.host} className="flex flex-wrap items-center justify-between gap-3 px-3 py-2.5">
              <div className="min-w-0">
                <p className="truncate font-mono text-sm text-slate-100">{c.host}</p>
                <p className="text-[11px] text-slate-500">{CANDIDATE_SOURCE[c.source]}</p>
              </div>
              {connected ? (
                <button
                  className="btn-secondary px-2.5 py-1 text-xs"
                  disabled={busyHost === c.host}
                  onClick={() => void point(c.host)}
                >
                  {busyHost === c.host ? "Pointing…" : "Point to new server"}
                </button>
              ) : (
                <a
                  className="btn-secondary px-2.5 py-1 text-xs"
                  href={cloudflareStartHref({
                    intent: "migration",
                    id: migrationId,
                    host: c.host,
                    next: nextPath,
                  })}
                >
                  Point to new server
                </a>
              )}
            </li>
          ))}
        </ul>
      )}

      {info && candidates.length === 0 && (
        <p className="mb-2 text-sm text-slate-400">
          We couldn&apos;t find any domains to suggest — enter the one you want to move.
        </p>
      )}

      {/* Manual entry: always available (subdomains, domains registered elsewhere). */}
      <div className="mt-4 flex flex-wrap items-end gap-2">
        <div className="min-w-0 grow">
          <label className="label">Another domain or subdomain</label>
          <input
            className="input"
            placeholder="example.com or app.example.com"
            value={manual}
            onChange={(e) => setManual(e.target.value)}
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck={false}
          />
        </div>
        {connected ? (
          <button
            className="btn-primary"
            disabled={manual.trim().length < 3 || busyHost === manual.trim().toLowerCase()}
            onClick={() => void point(manual.trim().toLowerCase())}
          >
            {busyHost ? "Pointing…" : "Point to new server"}
          </button>
        ) : (
          <a
            className="btn-primary"
            href={cloudflareStartHref({
              intent: "migration",
              id: migrationId,
              host: manual.trim().toLowerCase() || undefined,
              next: nextPath,
            })}
          >
            Connect Cloudflare
          </a>
        )}
      </div>
    </div>
  );
}
