"use client";

import { useState, useTransition } from "react";
import { Badge } from "@/components/ui/primitives";
import { disconnectCloudflare } from "@/lib/actions-cloudflare";
import { CloudflareConnect, CloudflareResultBanner } from "./CloudflareConnect";

/**
 * Account-level "Connected apps → Cloudflare" card in Settings.
 *
 * Cloudflare used to be a hidden, email-only setting. It's now a visible account
 * integration: connect once here (or from any DNS surface) and the same
 * connection powers mail records, pointing websites at a server, and the
 * post-migration domain cutover.
 */
export function CloudflareIntegration({
  connected: initialConnected,
  kind,
  oauthAvailable,
  scopeSummary,
  redirectUri,
}: {
  connected: boolean;
  kind: "oauth" | "token" | null;
  oauthAvailable: boolean;
  scopeSummary: string;
  redirectUri: string;
}) {
  const [connected, setConnected] = useState(initialConnected);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function disconnect() {
    setError(null);
    setStatus(null);
    start(async () => {
      const res = await disconnectCloudflare();
      if (res?.error) setError(res.error);
      else {
        setConnected(false);
        setStatus("Cloudflare disconnected. We can no longer read or change your DNS.");
      }
    });
  }

  return (
    <div className="card">
      <CloudflareResultBanner />

      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
        <h2 className="font-semibold">Cloudflare</h2>
        {connected ? (
          <Badge tone="green">Connected{kind === "token" ? " (API token)" : ""}</Badge>
        ) : (
          <Badge tone="slate">Not connected</Badge>
        )}
      </div>

      <p className="mb-4 text-sm text-slate-400">
        Connect the Cloudflare account that holds your domains and we can set DNS up for you: mail
        records for Business Email, pointing a website at its server, and moving your domains after a
        migration. We only ask to {scopeSummary}, and we only ever touch the records you ask us to —
        we never read your traffic, change your settings, or delete anything else. DNS changes can
        take a few minutes to reach everyone.
      </p>

      {error && (
        <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}
      {status && (
        <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          {status}
        </div>
      )}

      {connected ? (
        <div className="flex flex-wrap items-center gap-3">
          <button className="btn-secondary py-1.5 text-sm" onClick={disconnect} disabled={pending}>
            {pending ? "Disconnecting…" : "Disconnect Cloudflare"}
          </button>
          <span className="text-xs text-slate-500">
            {kind === "oauth"
              ? "Removes our access here and revokes it at Cloudflare. Records we already created stay in place."
              : "Deletes the stored API token. Records we already created stay in place."}
          </span>
        </div>
      ) : (
        <CloudflareConnect
          intent="settings"
          next="/dashboard/settings"
          connectedHint={false}
          onConnected={() => setConnected(true)}
        />
      )}

      {!oauthAvailable && (
        <p className="mt-4 border-t border-white/[0.06] pt-3 text-[11px] text-slate-600">
          Operator note: set CLOUDFLARE_OAUTH_CLIENT_ID and CLOUDFLARE_OAUTH_CLIENT_SECRET, and
          register <span className="font-mono">{redirectUri}</span> as the redirect URL on the
          Cloudflare OAuth client, to enable one-click connect.
        </p>
      )}
    </div>
  );
}

